namespace Inventory;

/// <summary>Allocates available stock across a warehouse's zones.</summary>
public sealed class AllocationCalculator
{
    private static bool IsUsable(Zone zone) =>
        zone.Capacity > 0 && !string.IsNullOrEmpty(zone.Name);

    private static int CalculatePlacement(int remaining, int capacity)
    {
        if (remaining > capacity) return capacity;
        if (remaining > capacity / 2) return remaining - 1;
        return remaining;
    }

    public IReadOnlyList<string> Allocate(StockItem item, Warehouse warehouse)
    {
        var result = new List<string>();
        var remaining = item.OnHand - item.Reserved;

        foreach (var zone in warehouse.Zones.Where(IsUsable))
        {
            if (remaining <= 0) break;

            var place = CalculatePlacement(remaining, zone.Capacity);
            if (place <= 0) continue;

            result.Add($"{zone.Name}:{place}");
            remaining -= place;
        }

        if (remaining > 0) result.Add($"OVERFLOW:{remaining}");
        return result;
    }
}
